For optimistic updates, you separate the optimistic UI state from the actual server state. Here's a useReducer implementation:

```javascript
const initialState = {
  data: null,
  status: 'idle', // 'idle' | 'pending' | 'success' | 'error'
  previousData: null,
  error: null
};

function reducer(state, action) {
  switch (action.type) {
    case 'OPTIMISTIC_UPDATE':
      return {
        ...state,
        previousData: state.data,
        data: action.payload,
        status: 'pending'
      };
    case 'SUCCESS':
      return {
        ...state,
        status: 'success',
        previousData: null
      };
    case 'ERROR':
      return {
        ...state,
        status: 'error',
        data: state.previousData, // rollback
        previousData: null,
        error: action.error
      };
    default:
      return state;
  }
}

// Usage in component:
const [state, dispatch] = useReducer(reducer, initialState);

const handleUpdate = async (newData) => {
  dispatch({ type: 'OPTIMISTIC_UPDATE', payload: newData });
  try {
    await api.update(newData);
    dispatch({ type: 'SUCCESS' });
  } catch (error) {
    dispatch({ type: 'ERROR', error });
  }
};
```

The useState approach uses useEffect for the server call:

```javascript
const [data, setData] = useState(null);
const [isPending, setIsPending] = useState(false);
const [error, setError] = useState(null);

const handleUpdate = async (newData) => {
  const previousData = data;
  setData(newData); // optimistic update
  setIsPending(true);
  try {
    await api.update(newData);
  } catch (error) {
    setData(previousData); // rollback
    setError(error);
  } finally {
    setIsPending(false);
  }
};
```

For race conditions with multiple rapid updates, use AbortController to cancel in-flight requests:

```javascript
const abortRef = useRef(null);

const handleUpdate = async (newData) => {
  // Cancel any in-flight request
  abortRef.current?.abort();

  const controller = new AbortController();
  abortRef.current = controller;

  setData(newData); // optimistic
  try {
    await api.update(newData, { signal: controller.signal });
  } catch (error) {
    if (error.name !== 'AbortError') {
      setData(previousData);
    }
  }
};
```

Alternatively, use version/sequence tracking to ignore stale responses:

```javascript
const versionRef = useRef(0);

const handleUpdate = async (newData) => {
  const currentVersion = ++versionRef.current;
  setData(newData);
  try {
    await api.update(newData);
    if (currentVersion !== versionRef.current) return; // stale response
    // process success
  } catch (error) {
    if (currentVersion !== versionRef.current) return;
    setData(previousData); // rollback
  }
};
```

Key strategies: 1) Store previous state before optimistic update, 2) Use AbortController to cancel stale requests, 3) Track request version to ignore outdated responses, 4) Consider a queue for sequential processing of dependent updates.

## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

